from typing import List

class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        def dfs(i: int, prev: int) -> int:
            if i == len(nums):
                return 0
            skip = dfs(i + 1, prev)
            take = 0
            if prev == -1 or nums[i] > nums[prev]:
                take = 1 + dfs(i + 1, i)
            return max(take, skip)

        return dfs(0, -1)

