from typing import List

class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        memo = {}

        def dfs(i: int, prev: int) -> int:
            if i == len(nums):
                return 0
            key = (i, prev)
            if key not in memo:
                best = dfs(i + 1, prev)
                if prev == -1 or nums[i] > nums[prev]:
                    best = max(best, 1 + dfs(i + 1, i))
                memo[key] = best
            return memo[key]

        return dfs(0, -1)

